#!/bin/sh
# Generated by sdk-kit 0.1.0 — do not edit; change sdk-kit and run "sdk-kit sync"
#
# wait-for-http.sh — wait until an HTTP endpoint answers with an expected status.
# POSIX sh; uses curl when present, otherwise wget (GNU or BusyBox).
#
# usage: wait-for-http.sh [-t TIMEOUT_S] [-i INTERVAL_S] [-s STATUS[,STATUS...]] [-H 'Name: value']... [-q] URL
#   -t  give up after TIMEOUT_S seconds (default 60)
#   -i  seconds between attempts (default 1)
#   -s  accepted status codes, comma separated (default 200); "2xx" accepts 200-299
#   -H  extra request header (repeatable); header values are never printed
#   -q  quiet: no progress messages
# exit: 0 ready, 1 timed out, 2 usage error or no HTTP client available
set -eu

timeout=60
interval=1
expect=200
quiet=0
headers_file=""

say() {
	[ "$quiet" -eq 1 ] || printf 'wait-for-http: %s\n' "$*" >&2
}

usage() {
	printf 'usage: %s [-t TIMEOUT_S] [-i INTERVAL_S] [-s STATUS[,STATUS...]] [-H HEADER]... [-q] URL\n' "$0" >&2
	exit 2
}

is_uint() {
	case $1 in '' | *[!0-9]*) return 1 ;; esac
	return 0
}

cleanup() {
	[ -z "$headers_file" ] || rm -f "$headers_file"
}
trap cleanup EXIT

if command -v curl >/dev/null 2>&1; then
	client=curl
elif command -v wget >/dev/null 2>&1; then
	client=wget
else
	say "neither curl nor wget is installed"
	exit 2
fi

headers_file=$(mktemp "${TMPDIR:-/tmp}/wait-for-http.XXXXXX")
while getopts "t:i:s:H:q" opt; do
	case $opt in
	t) timeout=$OPTARG ;;
	i) interval=$OPTARG ;;
	s) expect=$OPTARG ;;
	H) printf '%s\n' "$OPTARG" >>"$headers_file" ;;
	q) quiet=1 ;;
	*) usage ;;
	esac
done
shift $((OPTIND - 1))
[ $# -eq 1 ] || usage
url=$1
is_uint "$timeout" || usage
is_uint "$interval" || usage
[ "$interval" -ge 1 ] || interval=1
case $url in http://* | https://*) ;; *) usage ;; esac

# Prints the HTTP status code of one attempt, or 000 when there was no answer.
probe() {
	if [ "$client" = curl ]; then
		set -- -sS -o /dev/null -w '%{http_code}' --max-time 5
		while IFS= read -r line; do
			set -- "$@" -H "$line"
		done <"$headers_file"
		curl "$@" "$url" 2>/dev/null || true
	else
		set -- -S -O /dev/null -T 5
		while IFS= read -r line; do
			set -- "$@" --header "$line"
		done <"$headers_file"
		# wget -S prints the response status lines to stderr; the last one wins (redirects).
		code=$(wget "$@" "$url" 2>&1 | sed -n 's/^ *HTTP\/[0-9.]* \([0-9][0-9][0-9]\).*/\1/p' | tail -n 1) || true
		printf '%s' "${code:-000}"
	fi
}

accepted() {
	old_ifs=$IFS
	IFS=,
	for want in $expect; do
		IFS=$old_ifs
		case $want in
		[1-5]xx) [ "${1%??}" = "${want%xx}" ] && return 0 ;;
		*) [ "$1" = "$want" ] && return 0 ;;
		esac
	done
	IFS=$old_ifs
	return 1
}

start=$(date +%s)
attempt=0
while :; do
	attempt=$((attempt + 1))
	code=$(probe)
	[ -n "$code" ] || code=000
	if accepted "$code"; then
		say "$url answered $code after $attempt attempt(s)"
		exit 0
	fi
	now=$(date +%s)
	if [ $((now - start)) -ge "$timeout" ]; then
		say "timed out after ${timeout}s waiting for $url (last status $code, want $expect)"
		exit 1
	fi
	sleep "$interval"
done
